dp[mask][last] = count of permutations using exactly indices in mask, ending at last
for each mask, last:
    for each next index j not in mask:
        if nums[last] % nums[j] == 0 or nums[j] % nums[last] == 0:
            dp[mask | (1<<j)][j] += dp[mask][last]
answer = sum of dp[full_mask][i] for all i
